syntax = "proto3";

option csharp_namespace = "OrderApi.Grpc";

package orders;

service OrderService {
  rpc GetOrder (GetOrderRequest) returns (OrderReply);
  rpc ListOrders (ListOrdersRequest) returns (stream OrderReply);
}

message GetOrderRequest {
  string order_id = 1;
}

message OrderReply {
  string id = 1;
  string status = 2;
  int64 total_cents = 3;
}

public sealed class OrderGrpcService(IOrderQueries queries) : OrderService.OrderServiceBase
{
    public override async Task<OrderReply> GetOrder(
        GetOrderRequest request, ServerCallContext context)
    {
        var order = await queries.GetByIdAsync(request.OrderId, context.CancellationToken);
        if (order is null)
            throw new RpcException(new Status(StatusCode.NotFound, "Order not found"));

        return new OrderReply
        {
            Id = order.Id.ToString(),
            Status = order.Status,
            TotalCents = order.TotalCents
        };
    }
}

// Program.cs
builder.Services.AddGrpc();
var app = builder.Build();
app.MapGrpcService<OrderGrpcService>();
app.MapControllers(); // REST still available

var channel = GrpcChannel.ForAddress("https://order-service:8081", new GrpcChannelOptions
{
    HttpHandler = new SocketsHttpHandler
    {
        EnableMultipleHttp2Connections = true
    }
});

var client = new OrderService.OrderServiceClient(channel);

try
{
    var reply = await client.GetOrderAsync(
        new GetOrderRequest { OrderId = orderId.ToString() },
        cancellationToken: ct);
    return reply.Status;
}
catch (RpcException ex) when (ex.StatusCode == StatusCode.NotFound)
{
    return null;
}

// REST — public, browser-friendly
app.MapGet("/orders/{id:guid}", async (Guid id, IMediator mediator, CancellationToken ct) =>
{
    var order = await mediator.Send(new GetOrderQuery(id), ct);
    return order is null ? Results.NotFound() : Results.Ok(order);
});

